function trainBPE(text, merges){
  var sym=text.split('');
  var rank={}, n=0;
  for(var m=0;m<merges;m++){
    var cnt={};
    for(var i=0;i<sym.length-1;i++){ var k=sym[i]+'\u0001'+sym[i+1]; cnt[k]=(cnt[k]||0)+1; }
    var best=null,bn=-1; for(var k in cnt){ if(cnt[k]>bn){bn=cnt[k];best=k;} }
    if(!best) break;
    rank[best]=n++;
    var parts=best.split('\u0001'); var a=parts[0], b=parts[1];
    var ns=[];
    for(var i=0;i<sym.length;i++){
      if(i<sym.length-1 && sym[i]===a && sym[i+1]===b){ ns.push(a+b); i++; }
      else ns.push(sym[i]);
    }
    sym=ns;
  }
  return {vocab:sym, rank:rank};
}
function encode(text, rank){
  var sym=text.split(''); var changed=true;
  while(changed){
    changed=false; var bestI=-1, bestRank=Infinity;
    for(var i=0;i<sym.length-1;i++){
      var k=sym[i]+'\u0001'+sym[i+1];
      if(k in rank && rank[k]<bestRank){ bestRank=rank[k]; bestI=i; }
    }
    if(bestI>=0){ sym.splice(bestI,2, sym[bestI]+sym[bestI+1]); changed=true; }
  }
  return sym;
}
function decode(tokens){ return tokens.join(''); }
var EXPORTS={trainBPE:trainBPE,encode:encode,decode:decode};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

